    cy.visit('/');
    cy.login('user@example.com', 'password');
  });

  it('should display add to cart button on product page', () => {
    cy.visit('/products/1');
    cy.get('[data-testid="add-to-cart-btn"]').should('be.visible');
  });

  it('should increment cart count when adding product to cart', () => {
    cy.visit('/products/1');
    cy.get('[data-testid="cart-count"]').should('contain', '0');
    cy.get('[data-testid="add-to-cart-btn"]').click();
    cy.get('[data-testid="cart-count"]').should('contain', '1');
  });

  it('should display item in cart after adding to cart', () => {
    cy.visit('/products/1');
    cy.get('[data-testid="product-name"]').then(($el) => {
      const productName = $el.text();
      cy.get('[data-testid="add-to-cart-btn"]').click();
      cy.get('[data-testid="cart-icon"]').click();
      cy.get('[data-testid="cart-item"]').should('contain', productName);
    });
  });

  it('should add product to cart and verify all acceptance criteria', () => {
    cy.visit('/products/1');
    cy.get('[data-testid="add-to-cart-btn"]').should('be.visible');
    cy.get('[data-testid="cart-count"]').invoke('text').then((initialCount) => {
      const count = parseInt(initialCount);
      cy.get('[data-testid="product-name"]').invoke('text').then((productName) => {
        cy.get('[data-testid="add-to-cart-btn"]').click();
        cy.get('[data-testid="cart-count"]').should('contain', (count + 1).toString());
        cy.get('[data-testid="cart-icon"]').click();
        cy.get('[data-testid="cart-items-list"]').should('contain', productName);
      });
    });
  });
});
